DOCUMENT();

#############
# Load Macros
#############

loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "scaffold.pl",
  "parserPopUp.pl",
  "ORCCA.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');
COMMENT('This problem is scaffolded with multiple parts');

#######
# Setup
#######

Context('Numeric');
@x = random_subset(2,1..9);
@p = (Point(@x), -Point(@x), Point($x[0], -$x[1]), Point($x[1], -$x[0]));
@p = random_subset(4, @p);
for (0..3) {
  $ans[$_] = 'I'   if (($p[$_]->value)[0] > 0 && ($p[$_]->value)[1] > 0);
  $ans[$_] = 'II'  if (($p[$_]->value)[0] < 0 && ($p[$_]->value)[1] > 0);
  $ans[$_] = 'III' if (($p[$_]->value)[0] < 0 && ($p[$_]->value)[1] < 0);
  $ans[$_] = 'IV'  if (($p[$_]->value)[0] > 0 && ($p[$_]->value)[1] < 0);
  $d[$_] = DropDown(['I','II','III','IV'], $ans[$_], showInStatic => 0);
  $xposneg[$_] = (($p[$_]->value)[0] > 0) ? 'positive' : 'negative';
  $yposneg[$_] = (($p[$_]->value)[1] > 0) ? 'positive' : 'negative';
}
%qwords = (
  I => 'upper right',
  II => 'upper left',
  III => 'lower left',
  IV => 'lower right',
);
@ul = map {$qwords{$_}} @ans;

#############################
# Exercise Group Introduction
#############################

BEGIN_PGML
Which quadrant is the point in?

END_PGML

######
# Body
######

##########
# Scaffold
##########

Scaffold::Begin(numbered => 1,is_open => "correct_or_first_incorrect",can_open => always,);

#########
# Section
#########

Section::Begin("");

BEGIN_PGML
[`[$p[0]]`] [_]{$d[0]}{5}

END_PGML

##########
# Solution
##########

BEGIN_PGML_SOLUTION
The [`x`]-coordinate is [$xposneg[0]] and the [`y`]-coordinate is [$yposneg[0]], so the point is in the [$ul[0]] quadrant, which is Quadrant [$ans[0]].

END_PGML_SOLUTION

Section::End();

